const P=['happy','great','good','excited','proud','calm','grateful','love','fun'],N=['sad','tired','stress','stressed','anxious','bad','angry','lonely','overwhelmed'],NEG=['not','no','never',"don't","didn't","isn't","wasn't",'hardly'];
