function r(){const h=JSON.parse(localStorage.c||'[]').slice(-7);document.getElementById('h').innerHTML=h.map(e=>e.d+' '+(e.sc>0?'🙂':e.sc<0?'😔':'😐')+' ('+e.sc+')').join('<br>')}
r()</script></body></html>
